//! Pattern syntax parser producing an abstract syntax tree.

use super::class::ClassSet;
use super::unicode;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Assertion {
    StartText,
    EndText,
    StartLine,
    EndLine,
    WordBoundary,
    NotWordBoundary,
}

#[derive(Debug, Clone)]
pub enum Ast {
    Empty,
    Literal(char),
    Class(ClassSet),
    Group {
        node: Box<Ast>,
        index: Option<usize>,
        name: Option<String>,
    },
    Concat(Vec<Ast>),
    Alternate(Vec<Ast>),
    Repeat {
        node: Box<Ast>,
        min: u32,
        max: Option<u32>,
        greedy: bool,
    },
    Assert(Assertion),
}

#[derive(Debug, Clone, Copy)]
pub struct Flags {
    pub case_insensitive: bool,
    pub multi_line: bool,
    pub dot_matches_newline: bool,
    pub ignore_whitespace: bool,
    pub swap_greed: bool,
}

impl Default for Flags {
    fn default() -> Self {
        Flags {
            case_insensitive: false,
            multi_line: false,
            dot_matches_newline: false,
            ignore_whitespace: false,
            swap_greed: false,
        }
    }
}

pub struct Parser<'a> {
    chars: Vec<char>,
    pos: usize,
    pub group_count: usize,
    pub names: Vec<(String, usize)>,
    flags: Flags,
    _src: &'a str,
}

pub type PResult<T> = Result<T, String>;

impl<'a> Parser<'a> {
    pub fn new(pattern: &'a str) -> Self {
        Parser {
            chars: pattern.chars().collect(),
            pos: 0,
            group_count: 0,
            names: Vec::new(),
            flags: Flags::default(),
            _src: pattern,
        }
    }

    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn peek_at(&self, off: usize) -> Option<char> {
        self.chars.get(self.pos + off).copied()
    }

    fn bump(&mut self) -> Option<char> {
        let c = self.peek();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn eat(&mut self, c: char) -> bool {
        if self.peek() == Some(c) {
            self.pos += 1;
            true
        } else {
            false
        }
    }

    pub fn parse(&mut self) -> PResult<Ast> {
        let ast = self.parse_alternate()?;
        if self.pos < self.chars.len() {
            // Only unmatched ')' can get us here.
            return Err(format!(
                "unclosed group\nunopened group at position {}",
                self.pos
            ));
        }
        Ok(ast)
    }

    fn parse_alternate(&mut self) -> PResult<Ast> {
        let mut branches = vec![self.parse_concat()?];
        while self.peek() == Some('|') {
            self.pos += 1;
            branches.push(self.parse_concat()?);
        }
        if branches.len() == 1 {
            Ok(branches.pop().unwrap())
        } else {
            Ok(Ast::Alternate(branches))
        }
    }

    fn parse_concat(&mut self) -> PResult<Ast> {
        let mut items: Vec<Ast> = Vec::new();
        loop {
            match self.peek() {
                None | Some('|') | Some(')') => break,
                _ => {}
            }
            let saved_flags = self.flags;
            let item = self.parse_repeat()?;
            let _ = saved_flags;
            match item {
                Some(a) => items.push(a),
                None => continue, // flag-setting group, no node
            }
        }
        if items.is_empty() {
            Ok(Ast::Empty)
        } else if items.len() == 1 {
            Ok(items.pop().unwrap())
        } else {
            Ok(Ast::Concat(items))
        }
    }

    fn parse_repeat(&mut self) -> PResult<Option<Ast>> {
        let atom = match self.parse_atom()? {
            Some(a) => a,
            None => return Ok(None),
        };
        let mut node = atom;
        loop {
            let (min, max) = match self.peek() {
                Some('*') => {
                    self.pos += 1;
                    (0, None)
                }
                Some('+') => {
                    self.pos += 1;
                    (1, None)
                }
                Some('?') => {
                    self.pos += 1;
                    (0, Some(1))
                }
                Some('{') => {
                    if let Some((lo, hi, newpos)) = self.try_parse_counted() {
                        self.pos = newpos;
                        if let Some(h) = hi {
                            if h < lo {
                                return Err(format!(
                                    "repetition quantifier expects a valid decimal, but min > max ({lo} > {h})"
                                ));
                            }
                        }
                        (lo, hi)
                    } else {
                        break;
                    }
                }
                _ => break,
            };
            let mut greedy = !self.flags.swap_greed;
            if self.peek() == Some('?') {
                self.pos += 1;
                greedy = !greedy;
            } else if self.peek() == Some('+') {
                // possessive quantifiers are not supported by the reference engine
                return Err("repetition operator missing expression".to_string());
            }
            if matches!(node, Ast::Assert(_)) {
                // allowed but useless; keep it
            }
            node = Ast::Repeat {
                node: Box::new(node),
                min,
                max,
                greedy,
            };
        }
        Ok(Some(node))
    }

    fn try_parse_counted(&self) -> Option<(u32, Option<u32>, usize)> {
        let mut p = self.pos + 1; // skip '{'
        let start = p;
        while p < self.chars.len() && self.chars[p].is_ascii_digit() {
            p += 1;
        }
        if p == start {
            return None;
        }
        let lo: u32 = self.chars[start..p].iter().collect::<String>().parse().ok()?;
        if p < self.chars.len() && self.chars[p] == '}' {
            return Some((lo, Some(lo), p + 1));
        }
        if p < self.chars.len() && self.chars[p] == ',' {
            p += 1;
            let s2 = p;
            while p < self.chars.len() && self.chars[p].is_ascii_digit() {
                p += 1;
            }
            let hi = if p == s2 {
                None
            } else {
                Some(
                    self.chars[s2..p]
                        .iter()
                        .collect::<String>()
                        .parse::<u32>()
                        .ok()?,
                )
            };
            if p < self.chars.len() && self.chars[p] == '}' {
                return Some((lo, hi, p + 1));
            }
        }
        None
    }

    fn parse_atom(&mut self) -> PResult<Option<Ast>> {
        let c = match self.peek() {
            Some(c) => c,
            None => return Ok(None),
        };
        if self.flags.ignore_whitespace {
            if c.is_whitespace() {
                self.pos += 1;
                return Ok(None);
            }
            if c == '#' {
                while let Some(ch) = self.peek() {
                    self.pos += 1;
                    if ch == '\n' {
                        break;
                    }
                }
                return Ok(None);
            }
        }
        match c {
            '(' => self.parse_group().map(Some),
            '[' => {
                let cls = self.parse_class()?;
                Ok(Some(Ast::Class(cls)))
            }
            '.' => {
                self.pos += 1;
                let mut cls = if self.flags.dot_matches_newline {
                    ClassSet::any()
                } else {
                    ClassSet::any_except_nl()
                };
                cls.case_insensitive = self.flags.case_insensitive;
                Ok(Some(Ast::Class(cls)))
            }
            '^' => {
                self.pos += 1;
                Ok(Some(Ast::Assert(if self.flags.multi_line {
                    Assertion::StartLine
                } else {
                    Assertion::StartText
                })))
            }
            '$' => {
                self.pos += 1;
                Ok(Some(Ast::Assert(if self.flags.multi_line {
                    Assertion::EndLine
                } else {
                    Assertion::EndText
                })))
            }
            '\\' => self.parse_escape_atom().map(Some),
            '*' | '+' | '?' => Err("repetition operator missing expression".to_string()),
            ')' => Ok(None),
            _ => {
                self.pos += 1;
                Ok(Some(self.lit(c)))
            }
        }
    }

    fn lit(&self, c: char) -> Ast {
        if self.flags.case_insensitive {
            let mut cls = ClassSet::new();
            cls.push(c, c);
            cls.case_insensitive = true;
            Ast::Class(cls)
        } else {
            Ast::Literal(c)
        }
    }

    fn parse_group(&mut self) -> PResult<Ast> {
        self.pos += 1; // '('
        if self.eat('?') {
            match self.peek() {
                Some(':') => {
                    self.pos += 1;
                    let saved = self.flags;
                    let inner = self.parse_alternate()?;
                    if !self.eat(')') {
                        return Err("unclosed group".to_string());
                    }
                    self.flags = saved;
                    Ok(Ast::Group {
                        node: Box::new(inner),
                        index: None,
                        name: None,
                    })
                }
                Some('P') | Some('<') => {
                    if self.peek() == Some('P') {
                        self.pos += 1;
                        if self.peek() == Some('=') {
                            return Err("backreferences are not supported".to_string());
                        }
                    }
                    if self.peek() == Some('<') {
                        // could be lookbehind
                        if self.peek_at(1) == Some('=') || self.peek_at(1) == Some('!') {
                            return Err("look-around, including look-ahead and look-behind, is not supported".to_string());
                        }
                    }
                    if !self.eat('<') {
                        return Err("invalid capture group name".to_string());
                    }
                    let mut name = String::new();
                    loop {
                        match self.bump() {
                            Some('>') => break,
                            Some(ch) => {
                                if ch.is_alphanumeric() || ch == '_' || ch == '.' || ch == '[' || ch == ']' {
                                    name.push(ch)
                                } else {
                                    return Err(format!(
                                        "invalid capture group character: {ch}"
                                    ));
                                }
                            }
                            None => return Err("unclosed capture group name".to_string()),
                        }
                    }
                    if name.is_empty() {
                        return Err("empty capture group name".to_string());
                    }
                    self.group_count += 1;
                    let idx = self.group_count;
                    if self.names.iter().any(|(n, _)| n == &name) {
                        return Err(format!("duplicate capture group name: {name}"));
                    }
                    self.names.push((name.clone(), idx));
                    let saved = self.flags;
                    let inner = self.parse_alternate()?;
                    if !self.eat(')') {
                        return Err("unclosed group".to_string());
                    }
                    self.flags = saved;
                    Ok(Ast::Group {
                        node: Box::new(inner),
                        index: Some(idx),
                        name: Some(name),
                    })
                }
                Some('=') | Some('!') => {
                    Err("look-around, including look-ahead and look-behind, is not supported"
                        .to_string())
                }
                Some('#') => {
                    // comment group
                    while let Some(ch) = self.bump() {
                        if ch == ')' {
                            return Ok(Ast::Empty);
                        }
                    }
                    Err("unclosed group".to_string())
                }
                _ => {
                    // flags
                    let mut negate = false;
                    let mut newflags = self.flags;
                    loop {
                        match self.peek() {
                            Some('i') => {
                                self.pos += 1;
                                newflags.case_insensitive = !negate;
                            }
                            Some('m') => {
                                self.pos += 1;
                                newflags.multi_line = !negate;
                            }
                            Some('s') => {
                                self.pos += 1;
                                newflags.dot_matches_newline = !negate;
                            }
                            Some('x') => {
                                self.pos += 1;
                                newflags.ignore_whitespace = !negate;
                            }
                            Some('U') => {
                                self.pos += 1;
                                newflags.swap_greed = !negate;
                            }
                            Some('u') => {
                                self.pos += 1;
                            }
                            Some('R') => {
                                self.pos += 1;
                            }
                            Some('-') => {
                                if negate {
                                    return Err("duplicate flag negation".to_string());
                                }
                                self.pos += 1;
                                negate = true;
                            }
                            Some(':') => {
                                self.pos += 1;
                                let saved = self.flags;
                                self.flags = newflags;
                                let inner = self.parse_alternate()?;
                                if !self.eat(')') {
                                    return Err("unclosed group".to_string());
                                }
                                self.flags = saved;
                                return Ok(Ast::Group {
                                    node: Box::new(inner),
                                    index: None,
                                    name: None,
                                });
                            }
                            Some(')') => {
                                self.pos += 1;
                                self.flags = newflags;
                                return Ok(Ast::Empty);
                            }
                            Some(c) => return Err(format!("unrecognized flag: {c}")),
                            None => return Err("unclosed group".to_string()),
                        }
                    }
                }
            }
        } else {
            self.group_count += 1;
            let idx = self.group_count;
            let saved = self.flags;
            let inner = self.parse_alternate()?;
            if !self.eat(')') {
                return Err("unclosed group".to_string());
            }
            self.flags = saved;
            Ok(Ast::Group {
                node: Box::new(inner),
                index: Some(idx),
                name: None,
            })
        }
    }

    fn parse_escape_atom(&mut self) -> PResult<Ast> {
        self.pos += 1; // backslash
        let c = match self.bump() {
            Some(c) => c,
            None => return Err("incomplete escape sequence, reached end of pattern prematurely".to_string()),
        };
        match c {
            'A' => Ok(Ast::Assert(Assertion::StartText)),
            'z' => Ok(Ast::Assert(Assertion::EndText)),
            'b' => Ok(Ast::Assert(Assertion::WordBoundary)),
            'B' => Ok(Ast::Assert(Assertion::NotWordBoundary)),
            '<' => Ok(Ast::Assert(Assertion::WordBoundary)),
            '>' => Ok(Ast::Assert(Assertion::WordBoundary)),
            '1'..='9' => Err("backreferences are not supported".to_string()),
            _ => {
                self.pos -= 1;
                self.pos -= 1; // rewind to backslash
                let cls = self.parse_class_escape(false)?;
                match cls {
                    EscapeItem::Class(mut set) => {
                        set.case_insensitive = self.flags.case_insensitive;
                        Ok(Ast::Class(set))
                    }
                    EscapeItem::Char(ch) => Ok(self.lit(ch)),
                }
            }
        }
    }

    /// Parses an escape starting at the backslash. Used both inside and outside classes.
    fn parse_class_escape(&mut self, _in_class: bool) -> PResult<EscapeItem> {
        debug_assert_eq!(self.peek(), Some('\\'));
        self.pos += 1;
        let c = match self.bump() {
            Some(c) => c,
            None => {
                return Err(
                    "incomplete escape sequence, reached end of pattern prematurely".to_string(),
                )
            }
        };
        let item = match c {
            'n' => EscapeItem::Char('\n'),
            'r' => EscapeItem::Char('\r'),
            't' => EscapeItem::Char('\t'),
            'a' => EscapeItem::Char('\x07'),
            'f' => EscapeItem::Char('\x0C'),
            'v' => EscapeItem::Char('\x0B'),
            '0' => EscapeItem::Char('\0'),
            'e' => EscapeItem::Char('\x1B'),
            'd' => EscapeItem::Class(unicode::class_digit(false)),
            'D' => EscapeItem::Class(unicode::class_digit(true)),
            'w' => EscapeItem::Class(unicode::class_word(false)),
            'W' => EscapeItem::Class(unicode::class_word(true)),
            's' => EscapeItem::Class(unicode::class_space(false)),
            'S' => EscapeItem::Class(unicode::class_space(true)),
            'p' | 'P' => {
                let negate = c == 'P';
                let name = self.parse_unicode_class_name()?;
                let set = unicode::class_by_name(&name, negate)
                    .ok_or_else(|| format!("Unicode property not found: {name}"))?;
                EscapeItem::Class(set)
            }
            'x' => {
                let ch = self.parse_hex_escape()?;
                EscapeItem::Char(ch)
            }
            'u' => {
                let ch = self.parse_sized_hex(4)?;
                EscapeItem::Char(ch)
            }
            'U' => {
                let ch = self.parse_sized_hex(8)?;
                EscapeItem::Char(ch)
            }
            c if !c.is_alphanumeric() => EscapeItem::Char(c),
            c => return Err(format!("unrecognized escape sequence: \\{c}")),
        };
        Ok(item)
    }

    fn parse_unicode_class_name(&mut self) -> PResult<String> {
        if self.eat('{') {
            let mut name = String::new();
            loop {
                match self.bump() {
                    Some('}') => break,
                    Some(ch) => name.push(ch),
                    None => return Err("unclosed character class".to_string()),
                }
            }
            Ok(name)
        } else {
            match self.bump() {
                Some(ch) => Ok(ch.to_string()),
                None => Err("incomplete escape sequence, reached end of pattern prematurely"
                    .to_string()),
            }
        }
    }

    fn parse_hex_escape(&mut self) -> PResult<char> {
        if self.eat('{') {
            let mut s = String::new();
            loop {
                match self.bump() {
                    Some('}') => break,
                    Some(ch) => s.push(ch),
                    None => return Err("unclosed hex literal".to_string()),
                }
            }
            let v = u32::from_str_radix(&s, 16).map_err(|_| "invalid hexadecimal digit".to_string())?;
            char::from_u32(v).ok_or_else(|| "invalid Unicode scalar value".to_string())
        } else {
            self.parse_sized_hex(2)
        }
    }

    fn parse_sized_hex(&mut self, n: usize) -> PResult<char> {
        let mut s = String::new();
        for _ in 0..n {
            match self.bump() {
                Some(ch) if ch.is_ascii_hexdigit() => s.push(ch),
                _ => return Err("invalid hexadecimal digit".to_string()),
            }
        }
        let v = u32::from_str_radix(&s, 16).unwrap();
        char::from_u32(v).ok_or_else(|| "invalid Unicode scalar value".to_string())
    }

    fn parse_class(&mut self) -> PResult<ClassSet> {
        self.pos += 1; // '['
        let negated = self.eat('^');
        let mut set = ClassSet::new();
        let mut first = true;
        loop {
            let c = match self.peek() {
                Some(c) => c,
                None => return Err("unclosed character class".to_string()),
            };
            if c == ']' && !first {
                self.pos += 1;
                break;
            }
            first = false;
            if c == ']' {
                // literal ']' as first member
                self.pos += 1;
                set.push(']', ']');
                continue;
            }
            if c == '[' && self.peek_at(1) == Some(':') {
                if let Some((name, negate, newpos)) = self.try_posix_class() {
                    self.pos = newpos;
                    let cls = unicode::posix_class(&name, negate)
                        .ok_or_else(|| format!("unknown POSIX class name: {name}"))?;
                    set.union(&cls);
                    continue;
                }
            }
            // nested class union: [a[bc]]
            if c == '[' {
                let nested = self.parse_class()?;
                set.union(&nested);
                continue;
            }
            let lo = if c == '\\' {
                match self.parse_class_escape(true)? {
                    EscapeItem::Char(ch) => ch,
                    EscapeItem::Class(cls) => {
                        set.union(&cls);
                        continue;
                    }
                }
            } else {
                self.pos += 1;
                c
            };
            // range?
            if self.peek() == Some('-')
                && self.peek_at(1).is_some()
                && self.peek_at(1) != Some(']')
            {
                self.pos += 1;
                let nc = self.peek().unwrap();
                let hi = if nc == '\\' {
                    match self.parse_class_escape(true)? {
                        EscapeItem::Char(ch) => ch,
                        EscapeItem::Class(_) => {
                            return Err("invalid character class range".to_string())
                        }
                    }
                } else {
                    self.pos += 1;
                    nc
                };
                if hi < lo {
                    return Err(format!(
                        "invalid character class range, the start must be <= the end"
                    ));
                }
                set.push(lo, hi);
            } else {
                set.push(lo, lo);
            }
        }
        set.normalize();
        if negated {
            set.negate();
        }
        set.case_insensitive = self.flags.case_insensitive;
        Ok(set)
    }

    fn try_posix_class(&self) -> Option<(String, bool, usize)> {
        let mut p = self.pos + 2; // skip "[:"
        let negate = if self.chars.get(p) == Some(&'^') {
            p += 1;
            true
        } else {
            false
        };
        let start = p;
        while p < self.chars.len() && self.chars[p].is_ascii_alphabetic() {
            p += 1;
        }
        let name: String = self.chars[start..p].iter().collect();
        if self.chars.get(p) == Some(&':') && self.chars.get(p + 1) == Some(&']') {
            Some((name, negate, p + 2))
        } else {
            None
        }
    }
}

enum EscapeItem {
    Char(char),
    Class(ClassSet),
}

