        s
    }

    pub fn push(&mut self, lo: char, hi: char) {
        self.ranges.push((lo, hi));
    }

    pub fn union(&mut self, other: &ClassSet) {
        self.ranges.extend_from_slice(&other.ranges);
        self.normalize();
    }

    pub fn normalize(&mut self) {
        if self.ranges.is_empty() {
            return;
        }
        self.ranges.sort_by_key(|r| (r.0, r.1));
        let mut out: Vec<(char, char)> = Vec::with_capacity(self.ranges.len());
        for &(lo, hi) in &self.ranges {
            if let Some(last) = out.last_mut() {
                // merge if overlapping or adjacent
                let adjacent = next_char(last.1).map(|c| c == lo).unwrap_or(false);
                if lo <= last.1 || adjacent {
                    if hi > last.1 {
                        last.1 = hi;
                    }
                    continue;
                }
            }
            out.push((lo, hi));
        }
        self.ranges = out;
    }

    pub fn negate(&mut self) {
        self.normalize();
        let mut out = Vec::new();
        let mut cur = Some('\0');
        for &(lo, hi) in &self.ranges {
            if let Some(c) = cur {
                if c < lo {
                    if let Some(p) = prev_char(lo) {
                        out.push((c, p));
                    }
                }
            }
            cur = next_char(hi);
            if cur.is_none() {
                break;
            }
        }
        if let Some(c) = cur {
            out.push((c, char::MAX));
        }
        self.ranges = out;
    }

    pub fn subtract_char(&mut self, c: char) {
        let mut out = Vec::new();
        for &(lo, hi) in &self.ranges {
            if c < lo || c > hi {
                out.push((lo, hi));
                continue;
            }
            if let Some(p) = prev_char(c) {
                if lo <= p {
                    out.push((lo, p));
                }
            }
            if let Some(n) = next_char(c) {
                if n <= hi {
                    out.push((n, hi));
                }
            }
        }
        self.ranges = out;
    }

    #[inline]
    pub fn contains_raw(&self, c: char) -> bool {
        let mut lo = 0usize;
        let mut hi = self.ranges.len();
        while lo < hi {
            let mid = (lo + hi) / 2;
            let (a, b) = self.ranges[mid];
            if c < a {
                hi = mid;
            } else if c > b {
                lo = mid + 1;
            } else {
                return true;
            }
        }
        false
    }

    #[inline]
    pub fn matches(&self, c: char) -> bool {
        if self.contains_raw(c) {
            return true;
        }
        if self.case_insensitive {
            for alt in fold_variants(c) {
                if alt != c && self.contains_raw(alt) {
                    return true;
                }
            }
        }
        false
    }
}

pub fn fold_variants(c: char) -> Vec<char> {
    let mut v = Vec::with_capacity(3);
    let mut lower = c.to_lowercase();
    if lower.clone().count() == 1 {
        v.push(lower.next().unwrap());
    }
    let mut upper = c.to_uppercase();
    if upper.clone().count() == 1 {
        v.push(upper.next().unwrap());
    }
    // Special orbit members that simple mapping misses.
    match c {
        'ſ' => v.push('s'),
        's' | 'S' => v.push('ſ'),
        'K' | 'k' => v.push('\u{212A}'),
        '\u{212A}' => {
            v.push('k');
            v.push('K');
        }
        'Å' | 'å' => v.push('\u{212B}'),
        '\u{212B}' => {
            v.push('å');
            v.push('Å');
        }
        _ => {}
    }
    v
}

#[inline]
pub fn next_char(c: char) -> Option<char> {
    let v = c as u32;
    if v == 0xD7FF {
        return Some('\u{E000}');
    }
    char::from_u32(v + 1)
}

#[inline]
pub fn prev_char(c: char) -> Option<char> {
    let v = c as u32;
    if v == 0 {
        return None;
    }
    if v == 0xE000 {
        return Some('\u{D7FF}');
    }
    char::from_u32(v - 1)
}

