//! Compilation of the AST into a program for the Pike VM.

use super::ast::{Assertion, Ast};
use super::class::ClassSet;

#[derive(Debug, Clone)]
pub enum Inst {
    Char(char),
    Class(usize),
    Split(usize, usize),
    Jump(usize),
    Save(usize),
    Assert(Assertion),
    Match,
}

pub struct Program {
    pub insts: Vec<Inst>,
    pub classes: Vec<ClassSet>,
    pub n_slots: usize,
}

pub struct Compiler {
    insts: Vec<Inst>,
    classes: Vec<ClassSet>,
}

impl Compiler {
    pub fn new() -> Self {
        Compiler {
            insts: Vec::new(),
            classes: Vec::new(),
        }
    }

    pub fn compile(mut self, ast: &Ast, n_groups: usize) -> Program {
        self.emit(Inst::Save(0));
        self.compile_node(ast);
        self.emit(Inst::Save(1));
        self.emit(Inst::Match);
        Program {
            insts: self.insts,
            classes: self.classes,
            n_slots: (n_groups + 1) * 2,
        }
    }

    fn emit(&mut self, i: Inst) -> usize {
        self.insts.push(i);
        self.insts.len() - 1
    }

    fn here(&self) -> usize {
        self.insts.len()
    }

    fn add_class(&mut self, c: &ClassSet) -> usize {
        self.classes.push(c.clone());
        self.classes.len() - 1
    }

    fn compile_node(&mut self, ast: &Ast) {
        match ast {
            Ast::Empty => {}
            Ast::Literal(c) => {
                self.emit(Inst::Char(*c));
            }
            Ast::Class(cls) => {
                let idx = self.add_class(cls);
                self.emit(Inst::Class(idx));
            }
            Ast::Assert(a) => {
                self.emit(Inst::Assert(*a));
            }
            Ast::Concat(items) => {
                for i in items {
                    self.compile_node(i);
                }
            }
            Ast::Group { node, index, .. } => {
                if let Some(i) = index {
                    self.emit(Inst::Save(i * 2));
                    self.compile_node(node);
                    self.emit(Inst::Save(i * 2 + 1));
                } else {
                    self.compile_node(node);
                }
            }
            Ast::Alternate(branches) => {
                let mut jumps = Vec::new();
                let n = branches.len();
                for (i, b) in branches.iter().enumerate() {
                    if i + 1 == n {
                        self.compile_node(b);
                    } else {
                        let sp = self.emit(Inst::Split(0, 0));
                        let body = self.here();
                        self.compile_node(b);
                        let jp = self.emit(Inst::Jump(0));
                        jumps.push(jp);
                        let next = self.here();
                        self.insts[sp] = Inst::Split(body, next);
                    }
                }
                let end = self.here();
                for j in jumps {
                    self.insts[j] = Inst::Jump(end);
                }
            }
            Ast::Repeat {
                node,
                min,
                max,
                greedy,
            } => self.compile_repeat(node, *min, *max, *greedy),
        }
    }

    fn compile_repeat(&mut self, node: &Ast, min: u32, max: Option<u32>, greedy: bool) {
        const LIMIT: u32 = 1000;
        match max {
            None => {
                if min == 0 {
                    // star
                    let sp = self.emit(Inst::Split(0, 0));
                    let body = self.here();
                    self.compile_node(node);
                    self.emit(Inst::Jump(sp));
                    let end = self.here();
                    self.insts[sp] = if greedy {
                        Inst::Split(body, end)
                    } else {
                        Inst::Split(end, body)
                    };
                } else {
                    let n = min.min(LIMIT);
                    for _ in 0..n.saturating_sub(1) {
                        self.compile_node(node);
                    }
                    // plus for the last one
                    let body = self.here();
                    self.compile_node(node);
                    let sp = self.emit(Inst::Split(0, 0));
                    let end = self.here();
                    self.insts[sp] = if greedy {
                        Inst::Split(body, end)
                    } else {
                        Inst::Split(end, body)
                    };
                }
            }
            Some(mx) => {
                let mx = mx.min(LIMIT);
                let mn = min.min(mx);
                for _ in 0..mn {
                    self.compile_node(node);
                }
                let optional = mx - mn;
                let mut splits = Vec::new();
                for _ in 0..optional {
                    let sp = self.emit(Inst::Split(0, 0));
                    let body = self.here();
                    self.compile_node(node);
                    splits.push((sp, body));
                }
                let end = self.here();
                for (sp, body) in splits {
                    self.insts[sp] = if greedy {
                        Inst::Split(body, end)
                    } else {
                        Inst::Split(end, body)
                    };
                }
            }
        }
    }
}

