//! A Pike VM providing leftmost-first (Perl-like preference order) semantics
//! without backtracking.

use super::ast::Assertion;
use super::prog::{Inst, Program};

pub struct Vm<'p> {
    prog: &'p Program,
}

#[derive(Clone)]
struct Thread {
    pc: usize,
    caps: Vec<Option<usize>>,
}

impl<'p> Vm<'p> {
    pub fn new(prog: &'p Program) -> Self {
        Vm { prog }
    }

    /// Searches `text` starting at byte offset `start` (which must be a char boundary).
    pub fn search(&self, text: &str, start: usize, anchored: bool) -> Option<Vec<Option<usize>>> {
        let bytes = text.as_bytes();
        let mut clist: Vec<Thread> = Vec::new();
        let mut nlist: Vec<Thread> = Vec::new();
        let mut on_c: Vec<bool> = vec![false; self.prog.insts.len()];
        let mut on_n: Vec<bool> = vec![false; self.prog.insts.len()];
        let mut matched: Option<Vec<Option<usize>>> = None;

        let mut pos = start;
        loop {
            if matched.is_none() && (!anchored || pos == start) {
                let caps = vec![None; self.prog.n_slots];
                self.add_thread(text, pos, 0, caps, &mut clist, &mut on_c);
            }
            if clist.is_empty() && matched.is_some() {
                break;
            }
            let cur: Option<char> = if pos < bytes.len() {
                text[pos..].chars().next()
            } else {
                None
            };
            let clen = cur.map(|c| c.len_utf8()).unwrap_or(0);

            let mut i = 0;
            while i < clist.len() {
                let t = clist[i].clone();
                i += 1;
                match &self.prog.insts[t.pc] {
                    Inst::Char(c) => {
                        if cur == Some(*c) {
                            self.add_thread(text, pos + clen, t.pc + 1, t.caps, &mut nlist, &mut on_n);
                        }
                    }
                    Inst::Class(idx) => {
                        if let Some(ch) = cur {
                            if self.prog.classes[*idx].matches(ch) {
                                self.add_thread(
                                    text,
                                    pos + clen,
                                    t.pc + 1,
                                    t.caps,
                                    &mut nlist,
                                    &mut on_n,
                                );
                            }
                        }
                    }
                    Inst::Match => {
                        matched = Some(t.caps);
                        // Cut off lower-priority threads.
                        break;
                    }
                    _ => unreachable!("epsilon instruction in thread list"),
                }
            }

            std::mem::swap(&mut clist, &mut nlist);
            nlist.clear();
            std::mem::swap(&mut on_c, &mut on_n);
            for v in on_n.iter_mut() {
                *v = false;
            }

            if pos >= bytes.len() {
                break;
            }
            pos += clen;
            if clist.is_empty() && matched.is_some() {
                break;
            }
        }
        matched
    }

    fn add_thread(
        &self,
        text: &str,
        pos: usize,
        pc: usize,
        caps: Vec<Option<usize>>,
        list: &mut Vec<Thread>,
        seen: &mut [bool],
    ) {
        let mut stack: Vec<(usize, Vec<Option<usize>>)> = vec![(pc, caps)];
        // Depth-first with explicit stack, preserving priority order.
        // We push work in reverse so the preferred branch is processed first.
        let mut pending: Vec<(usize, Vec<Option<usize>>)> = Vec::new();
        while let Some((pc, caps)) = stack.pop() {
            pending.clear();
            if seen[pc] {
                continue;
            }
            seen[pc] = true;
            match &self.prog.insts[pc] {
                Inst::Jump(t) => stack.push((*t, caps)),
                Inst::Split(a, b) => {
                    // Preferred branch must be explored first: push b then a.
                    stack.push((*b, caps.clone()));
                    stack.push((*a, caps));
                }
                Inst::Save(slot) => {
                    let mut c2 = caps;
                    if *slot < c2.len() {
                        c2[*slot] = Some(pos);
                    }
                    stack.push((pc + 1, c2));
                }
                Inst::Assert(a) => {
                    if assertion_holds(*a, text, pos) {
                        stack.push((pc + 1, caps));
                    }
                }
                _ => list.push(Thread { pc, caps }),
            }
        }
    }
}

fn is_word_char(c: char) -> bool {
    c.is_alphanumeric() || c == '_'
}

fn char_before(text: &str, pos: usize) -> Option<char> {
    if pos == 0 {
        None
    } else {
        text[..pos].chars().next_back()
    }
}

fn char_at(text: &str, pos: usize) -> Option<char> {
    if pos >= text.len() {
        None
    } else {
        text[pos..].chars().next()
    }
}

fn assertion_holds(a: Assertion, text: &str, pos: usize) -> bool {
    match a {
        Assertion::StartText => pos == 0,
        Assertion::EndText => pos == text.len(),
        Assertion::StartLine => pos == 0 || char_before(text, pos) == Some('\n'),
        Assertion::EndLine => pos == text.len() || char_at(text, pos) == Some('\n'),
        Assertion::WordBoundary => {
            let before = char_before(text, pos).map(is_word_char).unwrap_or(false);
            let after = char_at(text, pos).map(is_word_char).unwrap_or(false);
            before != after
        }
        Assertion::NotWordBoundary => {
            let before = char_before(text, pos).map(is_word_char).unwrap_or(false);
            let after = char_at(text, pos).map(is_word_char).unwrap_or(false);
            before == after
        }
    }
}

