//! A small, dependency-free regular expression engine modelled on the syntax and
//! match semantics (leftmost-first, no backtracking) of Rust's `regex` crate.

pub mod ast;
pub mod class;
pub mod prog;
pub mod unicode;
pub mod vm;

use ast::Parser;
use prog::{Compiler, Program};
use vm::Vm;

#[derive(Debug)]
pub struct Error(pub String);

impl std::fmt::Display for Error {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.0)
    }
}

pub struct Regex {
    prog: Program,
    names: Vec<(String, usize)>,
    n_groups: usize,
    pattern: String,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Match {
    pub start: usize,
    pub end: usize,
}

pub struct Captures {
    slots: Vec<Option<usize>>,
    names: Vec<(String, usize)>,
}

impl Captures {
    pub fn get(&self, i: usize) -> Option<Match> {
        let s = *self.slots.get(i * 2)?;
        let e = *self.slots.get(i * 2 + 1)?;
        match (s, e) {
            (Some(s), Some(e)) => Some(Match { start: s, end: e }),
            _ => None,
        }
    }

    pub fn name(&self, n: &str) -> Option<Match> {
        let idx = self.names.iter().find(|(nm, _)| nm == n).map(|(_, i)| *i)?;
        self.get(idx)
    }

    pub fn has_name(&self, n: &str) -> bool {
        self.names.iter().any(|(nm, _)| nm == n)
    }

    pub fn len(&self) -> usize {
        self.slots.len() / 2
    }
}

impl Regex {
    pub fn new(pattern: &str) -> Result<Regex, Error> {
        let mut p = Parser::new(pattern);
        let ast = p.parse().map_err(|e| {
            Error(format!(
                "regex parse error:\n    {pattern}\n    ^\nerror: {e}"
            ))
        })?;
        let n_groups = p.group_count;
        let names = p.names.clone();
        let prog = Compiler::new().compile(&ast, n_groups);
        Ok(Regex {
            prog,
            names,
            n_groups,
            pattern: pattern.to_string(),
        })
    }

    pub fn as_str(&self) -> &str {
        &self.pattern
    }

    pub fn n_groups(&self) -> usize {
        self.n_groups
    }

    pub fn capture_names(&self) -> &[(String, usize)] {
        &self.names
    }

    pub fn find_at(&self, text: &str, start: usize) -> Option<Match> {
        let vm = Vm::new(&self.prog);
        let slots = vm.search(text, start, false)?;
        Some(Match {
            start: slots[0]?,
            end: slots[1]?,
        })
    }

    pub fn captures_at(&self, text: &str, start: usize) -> Option<Captures> {
        let vm = Vm::new(&self.prog);
        let slots = vm.search(text, start, false)?;
        Some(Captures {
            slots,
            names: self.names.clone(),
        })
    }

    pub fn is_match(&self, text: &str) -> bool {
        self.find_at(text, 0).is_some()
    }

    pub fn find_iter<'r, 't>(&'r self, text: &'t str) -> Matches<'r, 't> {
        Matches {
            re: self,
            text,
            pos: 0,
            last_end: 0,
            last_was_empty: false,
            done: false,
        }
    }

    pub fn captures_iter<'r, 't>(&'r self, text: &'t str) -> CaptureMatches<'r, 't> {
        CaptureMatches {
            re: self,
            text,
            pos: 0,
            done: false,
        }
    }
}

pub struct Matches<'r, 't> {
    re: &'r Regex,
    text: &'t str,
    pos: usize,
    last_end: usize,
    last_was_empty: bool,
    done: bool,
}

impl<'r, 't> Iterator for Matches<'r, 't> {
    type Item = Match;
    fn next(&mut self) -> Option<Match> {
        let _ = (self.last_end, self.last_was_empty);
        if self.done || self.pos > self.text.len() {
            return None;
        }
        let m = self.re.find_at(self.text, self.pos)?;
        if m.end == m.start {
            // Advance one character to avoid an infinite loop on empty matches.
            self.pos = next_boundary(self.text, m.end);
            if m.end >= self.text.len() {
                self.done = true;
            }
        } else {
            self.pos = m.end;
        }
        Some(m)
    }
}

pub struct CaptureMatches<'r, 't> {
    re: &'r Regex,
    text: &'t str,
    pos: usize,
    done: bool,
}

impl<'r, 't> Iterator for CaptureMatches<'r, 't> {
    type Item = Captures;
    fn next(&mut self) -> Option<Captures> {
        if self.done || self.pos > self.text.len() {
            return None;
        }
        let caps = self.re.captures_at(self.text, self.pos)?;
        let m = caps.get(0).unwrap();
        if m.end == m.start {
            self.pos = next_boundary(self.text, m.end);
            if m.end >= self.text.len() {
                self.done = true;
            }
        } else {
            self.pos = m.end;
        }
        Some(caps)
    }
}

fn next_boundary(text: &str, pos: usize) -> usize {
    if pos >= text.len() {
        return pos + 1;
    }
    let mut p = pos + 1;
    while p < text.len() && !text.is_char_boundary(p) {
        p += 1;
    }
    p
}

/// Expands `$1`, `${name}`, `$name` and `$$` references in a replacement template.
pub fn expand(caps: &Captures, template: &str, dst: &mut String) {
    let bytes = template.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        let b = bytes[i];
        if b != b'$' {
            let ch = template[i..].chars().next().unwrap();
            dst.push(ch);
            i += ch.len_utf8();
            continue;
        }
        if i + 1 >= bytes.len() {
            dst.push('$');
            i += 1;
            continue;
        }
        if bytes[i + 1] == b'$' {
            dst.push('$');
            i += 2;
            continue;
        }
        if bytes[i + 1] == b'{' {
            // ${name} / ${1}
            if let Some(close) = template[i + 2..].find('}') {
                let name = &template[i + 2..i + 2 + close];
                push_group(caps, name, dst);
                i = i + 2 + close + 1;
                continue;
            }
            dst.push('$');
            i += 1;
            continue;
        }
        // bare name: [0-9A-Za-z_]+
        let start = i + 1;
        let mut end = start;
        while end < bytes.len() && (bytes[end].is_ascii_alphanumeric() || bytes[end] == b'_') {
            end += 1;
        }
        if end == start {
            dst.push('$');
            i += 1;
            continue;
        }
        let name = &template[start..end];
        push_group(caps, name, dst);
        i = end;
    }
}

fn push_group(caps: &Captures, name: &str, dst: &mut String) {
    let _ = name;
    if name.is_empty() {
        return;
    }
    if name.bytes().all(|b| b.is_ascii_digit()) {
        if let Ok(n) = name.parse::<usize>() {
            if let Some(m) = caps.get(n) {
                dst.push_str(caps.text_of(m));
            }
        }
        return;
    }
    if let Some(m) = caps.name(name) {
        dst.push_str(caps.text_of(m));
    }
}

impl Captures {
    fn text_of(&self, _m: Match) -> &str {
        // Filled in by CapturesWithText; see `expand_with_text`.
        ""
    }
}

/// Expands a replacement template using `haystack` for group text.
pub fn expand_with_text(caps: &Captures, haystack: &str, template: &str, dst: &mut String) {
    let bytes = template.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        let b = bytes[i];
        if b != b'$' {
            let ch = template[i..].chars().next().unwrap();
            dst.push(ch);
            i += ch.len_utf8();
            continue;
        }
        if i + 1 >= bytes.len() {
            dst.push('$');
            i += 1;
            continue;
        }
        if bytes[i + 1] == b'$' {
            dst.push('$');
            i += 2;
            continue;
        }
        if bytes[i + 1] == b'{' {
            if let Some(close) = template[i + 2..].find('}') {
                let name = &template[i + 2..i + 2 + close];
                push_group_text(caps, haystack, name, dst);
                i = i + 2 + close + 1;
                continue;
            }
            dst.push('$');
            i += 1;
            continue;
        }
        let start = i + 1;
        let mut end = start;
        while end < bytes.len() && (bytes[end].is_ascii_alphanumeric() || bytes[end] == b'_') {
            end += 1;
        }
        if end == start {
            dst.push('$');
            i += 1;
            continue;
        }
        let name = &template[start..end];
        push_group_text(caps, haystack, name, dst);
        i = end;
    }
}

fn push_group_text(caps: &Captures, haystack: &str, name: &str, dst: &mut String) {
    if name.is_empty() {
        return;
    }
    let m = if name.bytes().all(|b| b.is_ascii_digit()) {
        name.parse::<usize>().ok().and_then(|n| caps.get(n))
    } else {
        caps.name(name)
    };
    if let Some(m) = m {
        dst.push_str(&haystack[m.start..m.end]);
    }
}

