                let name = &template[i + 2..i + 2 + close];
                push_group(caps, name, dst);
                i = i + 2 + close + 1;
                continue;
            }
            dst.push('$');
            i += 1;
            continue;
        }
        // bare name: [0-9A-Za-z_]+
        let start = i + 1;
        let mut end = start;
        while end < bytes.len() && (bytes[end].is_ascii_alphanumeric() || bytes[end] == b'_') {
            end += 1;
        }
        if end == start {
            dst.push('$');
            i += 1;
            continue;
        }
        let name = &template[start..end];
        push_group(caps, name, dst);
        i = end;
    }
}

fn push_group(caps: &Captures, name: &str, dst: &mut String) {
    let _ = name;
    if name.is_empty() {
        return;
    }
    if name.bytes().all(|b| b.is_ascii_digit()) {
        if let Ok(n) = name.parse::<usize>() {
            if let Some(m) = caps.get(n) {
                dst.push_str(caps.text_of(m));
            }
        }
        return;
    }
    if let Some(m) = caps.name(name) {
        dst.push_str(caps.text_of(m));
    }
}

impl Captures {
    fn text_of(&self, _m: Match) -> &str {
        // Filled in by CapturesWithText; see `expand_with_text`.
        ""
    }
}

/// Expands a replacement template using `haystack` for group text.
pub fn expand_with_text(caps: &Captures, haystack: &str, template: &str, dst: &mut String) {
    let bytes = template.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        let b = bytes[i];
        if b != b'$' {
            let ch = template[i..].chars().next().unwrap();
            dst.push(ch);
            i += ch.len_utf8();
            continue;
        }
        if i + 1 >= bytes.len() {
            dst.push('$');
            i += 1;
            continue;
        }
        if bytes[i + 1] == b'$' {
            dst.push('$');
            i += 2;
            continue;
        }
        if bytes[i + 1] == b'{' {
            if let Some(close) = template[i + 2..].find('}') {
                let name = &template[i + 2..i + 2 + close];
                push_group_text(caps, haystack, name, dst);
                i = i + 2 + close + 1;
                continue;
            }
            dst.push('$');
            i += 1;
            continue;
        }
        let start = i + 1;
        let mut end = start;
        while end < bytes.len() && (bytes[end].is_ascii_alphanumeric() || bytes[end] == b'_') {
            end += 1;
        }
        if end == start {
            dst.push('$');
            i += 1;
            continue;
        }
        let name = &template[start..end];
        push_group_text(caps, haystack, name, dst);
        i = end;
    }
}

fn push_group_text(caps: &Captures, haystack: &str, name: &str, dst: &mut String) {
    if name.is_empty() {
        return;
    }
    let m = if name.bytes().all(|b| b.is_ascii_digit()) {
        name.parse::<usize>().ok().and_then(|n| caps.get(n))
    } else {
        caps.name(name)
    };
    if let Some(m) = m {
        dst.push_str(&haystack[m.start..m.end]);
    }
}

