#!/usr/bin/env python3
"""Generates src/rx/unicode_tables.rs from the Python runtime's Unicode database.

The output is committed to the repository; the build itself does not run this.
"""
import sys
import unicodedata

MAX = 0x110000

def ranges_from_predicate(pred):
    out = []
    start = None
    for cp in range(MAX):
        ok = pred(cp)
        if ok and start is None:
            start = cp
        elif not ok and start is not None:
            out.append((start, cp - 1))
            start = None
    if start is not None:
        out.append((start, MAX - 1))
    return out


def cat(cp):
    try:
        return unicodedata.category(chr(cp))
    except ValueError:
        return "Cn"


def main():
    cats = {}
    for cp in range(MAX):
        c = cat(cp)
        cats.setdefault(c, []).append(cp)

    # Compress each category into ranges.
    cat_ranges = {}
    for name, cps in cats.items():
        if name == "Cn":
            continue
        rs = []
        start = prev = None
        for cp in cps:
            if start is None:
                start = prev = cp
            elif cp == prev + 1:
                prev = cp
            else:
                rs.append((start, prev))
                start = prev = cp
        if start is not None:
            rs.append((start, prev))
        cat_ranges[name] = rs

    lines = []
    lines.append("//! Generated by tools/gen_unicode.py from Unicode %s. Do not edit by hand."
                 % unicodedata.unidata_version)
    lines.append("")
    lines.append("pub static CATEGORIES: &[(&str, &[(u32, u32)])] = &[")
    for name in sorted(cat_ranges):
        rs = cat_ranges[name]
        lines.append('    ("%s", &[' % name)
        chunk = []
        for lo, hi in rs:
            chunk.append("(%d,%d)" % (lo, hi))
        # wrap
        buf = ""
        for item in chunk:
            if len(buf) + len(item) + 1 > 96:
                lines.append("        " + buf)
                buf = ""
            buf += item + ","
        if buf:
            lines.append("        " + buf)
        lines.append("    ]),")
    lines.append("];")
    lines.append("")

    # White_Space property (from PropList); approximate via Python's isspace plus
    # the explicit list, which matches Unicode's White_Space exactly.
    ws = set([0x9, 0xA, 0xB, 0xC, 0xD, 0x20, 0x85, 0xA0, 0x1680,
              0x2028, 0x2029, 0x202F, 0x205F, 0x3000])
    for cp in range(0x2000, 0x200B):
        ws.add(cp)
    ws.add(0x1680)
    ws_ranges = ranges_from_predicate(lambda cp: cp in ws)
    emit_ranges(lines, "WHITE_SPACE", ws_ranges)

    # Canonical decompositions, fully expanded, excluding Hangul (algorithmic).
    decomps = []
    for cp in range(MAX):
        ch = chr(cp)
        if 0xAC00 <= cp <= 0xD7A3:
            continue
        d = unicodedata.decomposition(ch)
        if not d or d.startswith("<"):
            continue
        nfd = unicodedata.normalize("NFD", ch)
        if nfd == ch:
            continue
        decomps.append((cp, nfd))
    lines.append("pub static CANONICAL_DECOMP: &[(u32, &str)] = &[")
    buf = ""
    for cp, s in decomps:
        item = "(%d,%s)," % (cp, rust_str(s))
        if len(buf) + len(item) > 96:
            lines.append("    " + buf)
            buf = ""
        buf += item
    if buf:
        lines.append("    " + buf)
    lines.append("];")
    lines.append("")

    with open("src/rx/unicode_tables.rs", "w") as f:
        f.write("\n".join(lines) + "\n")
    print("categories: %d, decomps: %d" % (len(cat_ranges), len(decomps)), file=sys.stderr)


def rust_str(s):
    out = '"'
    for ch in s:
        out += "\\u{%x}" % ord(ch)
    return out + '"'


def emit_ranges(lines, name, rs):
    lines.append("pub static %s: &[(u32, u32)] = &[" % name)
    buf = ""
    for lo, hi in rs:
        item = "(%d,%d)," % (lo, hi)
        if len(buf) + len(item) > 96:
            lines.append("    " + buf)
            buf = ""
        buf += item
    if buf:
        lines.append("    " + buf)
    lines.append("];")
    lines.append("")


main()

