}

pub fn class_word(negate: bool) -> ClassSet {
    let mut s = category_set("L").unwrap_or_default();
    if let Some(m) = category_set("M") {
        s.union(&m);
    }
    if let Some(nd) = category_set("Nd") {
        s.union(&nd);
    }
    if let Some(pc) = category_set("Pc") {
        s.union(&pc);
    }
    s.union(&ClassSet::from_ranges(&[('\u{200C}', '\u{200D}')]));
    if negate {
        s.negate();
    }
    s
}

pub fn posix_class(name: &str, negate: bool) -> Option<ClassSet> {
    let mut s = match name {
        "alpha" => category_set("L")?,
        "digit" => ClassSet::from_ranges(&[('0', '9')]),
        "alnum" => {
            let mut a = category_set("L")?;
            a.union(&category_set("Nd")?);
            a
        }
        "upper" => category_set("Lu")?,
        "lower" => category_set("Ll")?,
        "space" => set_of(tbl::WHITE_SPACE),
        "blank" => ClassSet::from_ranges(&[('\t', '\t'), (' ', ' ')]),
        "cntrl" => category_set("Cc")?,
        "graph" => {
            let mut a = ClassSet::any();
            let mut excl = set_of(tbl::WHITE_SPACE);
            excl.union(&category_set("Cc")?);
            excl.union(&category_set("Cf")?);
            excl.union(&category_set("Cs")?);
            excl.negate();
            a = intersect(&a, &excl);
            a
        }
        "print" => {
            let mut a = posix_class("graph", false)?;
            a.union(&ClassSet::from_ranges(&[(' ', ' ')]));
            a
        }
        "punct" => {
            let mut a = category_set("P")?;
            a.union(&category_set("S")?);
            a
        }
        "word" => class_word(false),
        "xdigit" => ClassSet::from_ranges(&[('0', '9'), ('A', 'F'), ('a', 'f')]),
        "ascii" => ClassSet::from_ranges(&[('\0', '\u{7F}')]),
        _ => return None,
    };
    if negate {
        s.negate();
    }
    Some(s)
}

fn intersect(a: &ClassSet, b: &ClassSet) -> ClassSet {
    let mut out = Vec::new();
    for &(alo, ahi) in &a.ranges {
        for &(blo, bhi) in &b.ranges {
            let lo = alo.max(blo);
            let hi = ahi.min(bhi);
            if lo <= hi {
                out.push((lo, hi));
            }
        }
    }
    ClassSet::from_ranges(&out)
}

/// Canonical decomposition (NFD) of a single character, if any.
pub fn nfd_char(c: char) -> Option<&'static str> {
    let cp = c as u32;
    let t = tbl::CANONICAL_DECOMP;
    let mut lo = 0usize;
    let mut hi = t.len();
    while lo < hi {
        let mid = (lo + hi) / 2;
        if t[mid].0 < cp {
            lo = mid + 1;
        } else if t[mid].0 > cp {
            hi = mid;
        } else {
            return Some(t[mid].1);
        }
    }
    None
}

pub fn is_mark(c: char) -> bool {
    for (name, ranges) in tbl::CATEGORIES {
        if name.starts_with('M') {
            let cp = c as u32;
            if ranges.iter().any(|&(lo, hi)| cp >= lo && cp <= hi) {
                return true;
            }
        }
    }
    false
}

