//! Unicode-derived character classes used by the pattern engine.

use super::class::ClassSet;
use super::unicode_tables as tbl;

fn ranges_of_categories(prefix: &str) -> Vec<(char, char)> {
    let mut out = Vec::new();
    for (name, ranges) in tbl::CATEGORIES {
        if *name == prefix || (prefix.len() == 1 && name.starts_with(prefix)) {
            for &(lo, hi) in *ranges {
                if let (Some(a), Some(b)) = (char::from_u32(lo), char::from_u32(hi)) {
                    out.push((a, b));
                }
            }
        }
    }
    out
}

fn set_of(ranges: &[(u32, u32)]) -> ClassSet {
    let v: Vec<(char, char)> = ranges
        .iter()
        .filter_map(|&(lo, hi)| Some((char::from_u32(lo)?, char::from_u32(hi)?)))
        .collect();
    ClassSet::from_ranges(&v)
}

pub fn category_set(name: &str) -> Option<ClassSet> {
    let known = [
        "Lu", "Ll", "Lt", "Lm", "Lo", "Mn", "Mc", "Me", "Nd", "Nl", "No", "Pc", "Pd", "Ps", "Pe",
        "Pi", "Pf", "Po", "Sm", "Sc", "Sk", "So", "Zs", "Zl", "Zp", "Cc", "Cf", "Cs", "Co", "L",
        "M", "N", "P", "S", "Z", "C",
    ];
    if !known.contains(&name) {
        return None;
    }
    let r = ranges_of_categories(name);
    if r.is_empty() {
        return None;
    }
    Some(ClassSet::from_ranges(&r))
}

fn normalize_name(s: &str) -> String {
    s.chars()
        .filter(|c| *c != '_' && *c != '-' && *c != ' ')
        .flat_map(|c| c.to_lowercase())
        .collect()
}

